/* figma 155:13094 — geometry is the spec, frost is by eye */
.gcard {
  width: 316px;
  height: 316px;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.6);
}

/* The band: 60 ticks over 300deg, leaving
   60deg of gap at the bottom. Each tick is placed
   from its own index, so the count is the only thing that
   changes when the band gets finer. */
.hwheel-tick {
  --start: 120deg;
  --sweep: 300deg;
  --step: calc(var(--sweep) / 59);
  rotate: calc(var(--start) + var(--step) * var(--i));
}

/* the lit ticks carry a travelling wave whose amplitude
   scales with the reading — at 0 the ring is a static gauge,
   and this is the number that decides whether it looks
   alive */
--wave-amp: calc(1 + var(--reading) * 2.6);

